using System;using System.Collections.Generic;using RimWorld;using UnityEngine;using Verse;using Verse.AI;
namespace ElementalHearts {
 public static class GlacialEvolution {
  public const string DefName="EH_GlacialAscendant";
  public static bool Active(Pawn p){if(p==null||p.health==null)return false;foreach(var h in p.health.hediffSet.hediffs)if(h.def.defName==DefName)return true;return false;}
  public static bool Water(Pawn p){return Active(p)||WaterKitUpgrade.HasAscension(p);}
  public static HediffComp_GlacialMastery Mastery(Pawn p){if(p==null||p.health==null)return null;foreach(var h in p.health.hediffSet.hediffs){var c=h.TryGetComp<HediffComp_GlacialMastery>();if(c!=null)return c;}return null;}
  public static string Problem(Pawn p){var c=Mastery(p);if(c==null||!WaterKitUpgrade.HasAscension(p))return "Requires ordinary Water ascension.";if(!AzureRules.Ready(c.kills,c.parent.ageTicks))return "Requires 150 unique hostile non-animal kills and ten ascendant days.";if(!ElementalTeaching.Ready(p)||ElementalTeachingSession.Busy(p)||ElementalAnimationBridge.Controlled(p)||HediffComp_ElementalTransform.Transforming(p)||AzureEvolution.Evolving(p)||p.CurJobDef==DefDatabase<JobDef>.GetNamed("EH_WaterCounter"))return "Finish the current controlled action first.";return null;}
  public static bool Upgrade(Pawn p){HediffWithComps root=null;foreach(var h in p.health.hediffSet.hediffs)if(h.def.defName==WaterKitUpgrade.DefName)root=h as HediffWithComps;if(root==null)return Active(p);AzureLineage.Rebind(root,DefDatabase<HediffDef>.GetNamed(DefName));p.health.Notify_HediffChanged(root);var transform=root.TryGetComp<HediffComp_ElementalTransform>();if(transform!=null)transform.RebuildAzureKit();if(p.Spawned)foreach(var c in root.comps)c.Notify_Spawned();return true;}
  public static bool Complete(Pawn p){var c=Mastery(p);if(c==null||!WaterKitUpgrade.HasAscension(p)||!AzureRules.Ready(c.kills,c.parent.ageTicks)||!ElementalTeaching.Ready(p))return false;if(!Upgrade(p))return false;p.Drawer.renderer.SetAllGraphicsDirty();ElementalAudio.Play(p,"EH_TransformLock");Messages.Message(p.LabelShort+" has evolved into a Glacial Ascendant!",p,MessageTypeDefOf.PositiveEvent,false);return true;}
  static readonly float[] ranges={12f,7f,5f,14f};
  public static float Range(Pawn p,WaterPower power){return Active(p)?ranges[(int)power]:WaterAbilityRules.Range(power);}
  public static int Warmup(Pawn p,WaterPower power){return Active(p)&&power==WaterPower.Judgement?30:WaterAbilityRules.Warmup(power);}
  public static int Cooldown(Pawn p,WaterPower power){return Active(p)&&power==WaterPower.Judgement?1920:WaterAbilityRules.Cooldown(power);}
  public static readonly string[] Names={"Glacial Crescent","Frostwake Step","Crystal Vortex","Absolute Zero"};
  public static readonly string[] Details={"An ice-edged crescent travels a twelve-cell clear lane. Each victim is hit once and surviving damaging hits build Pressure.","Glide up to seven cells to an empty melee flank with a crystalline wake and regal afterimages. One arrival strike; blocked routes interrupt safely.","Spin a crystalline sword blade through five clear cells. Eight rotating frames show one strike per eligible victim; surviving damaging hits build Pressure.","A snowflake sigil warns for half a second before one focused ice-column impact and a three-cell controlled burst. Consumes up to three owned Pressure stacks; primary and secondary targets never receive duplicate hits."};
 }
 public sealed class HediffCompProperties_GlacialMastery:HediffCompProperties {public HediffCompProperties_GlacialMastery(){compClass=typeof(HediffComp_GlacialMastery);}}
 public sealed class HediffComp_GlacialMastery:HediffComp {
  public int kills;HashSet<int> victims=new HashSet<int>();
  public override void CompExposeData(){Scribe_Values.Look(ref kills,"EH_glacialMasteryKills");Scribe_Collections.Look(ref victims,"EH_glacialMasteryVictims",LookMode.Value);if(victims==null)victims=new HashSet<int>();}
  public override void Notify_KilledPawn(Pawn victim,DamageInfo? info){if(GlacialEvolution.Active(Pawn)||victim==null||!AzureRules.CountKill(victim.HostileTo(Pawn),victim.RaceProps.Animal,victim==Pawn)||!victims.Add(victim.thingIDNumber))return;kills++;}
  public override string CompTipStringExtra{get{return GlacialEvolution.Active(Pawn)?"Glacial evolution complete.":"Glacial mastery: "+kills+" / 150 unique hostile non-animal kills; "+(parent.ageTicks/60000f).ToString("0.0")+" / 10 ascendant days.";}}
  public override void CompPostTickInterval(ref float adjustment,int delta){if(Pawn.Spawned&&Pawn.CurJobDef==DefDatabase<JobDef>.GetNamed("EH_EvolveGlacial"))EvolutionCinematic.Track(Pawn);}
  public override IEnumerable<Gizmo> CompGetGizmos(){if(!ElementalCombatPolicy.Controlled(Pawn)||GlacialEvolution.Active(Pawn))yield break;var c=new Command_Action{defaultLabel="Evolve: Glacial",defaultDesc=CompTipStringExtra+"\nA 4.5-second frost ritual grants five Glacial techniques, helmetless royal regalia, a crystalline sword, an ice halo and evolved defense. No resource cost; interruption keeps readiness.",icon=GlacialVfx.Icon(5),groupable=false,action=()=>{if(GlacialEvolution.Problem(Pawn)==null)Pawn.jobs.TryTakeOrderedJob(JobMaker.MakeJob(DefDatabase<JobDef>.GetNamed("EH_EvolveGlacial"),Pawn),JobTag.Misc);}};var reason=GlacialEvolution.Problem(Pawn);if(reason!=null)c.Disable(reason);yield return c;if(DebugSettings.godMode)yield return new DevEvolutionReadyCommand{isEligible=()=>WaterKitUpgrade.HasAscension(Pawn)&&GlacialEvolution.Mastery(Pawn)==this,defaultLabel="DEV: Evolution-Ready",defaultDesc="God Mode only. Unlock Glacial requirements; press Evolve: Glacial to perform the ritual.",icon=GlacialVfx.Icon(5),groupable=false,action=()=>{if(DebugSettings.godMode){kills=Math.Max(kills,150);parent.ageTicks=Math.Max(parent.ageTicks,600000);}}};}
 }
 public sealed class ThoughtWorker_WaterResolve:ThoughtWorker_Hediff {protected override ThoughtState CurrentStateInternal(Pawn p){return GlacialEvolution.Active(p)?ThoughtState.ActiveAtStage(1):base.CurrentStateInternal(p);}}
}
